using Rasta.ProjectManagment.Domain.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;  namespace Rasta.ProjectManagment.Infrastructure.Persistence.Configurations;  public class ProjectConfiguration : IEntityTypeConfiguration<Project> {     public void Configure(EntityTypeBuilder<Project> builder)     {         builder.Property(t => t.ProjectName)             .HasMaxLength(50)             .IsUnicode()             .IsRequired();          builder.Property(t => t.ProjectTypeId)            .IsRequired();          builder.Property(t => t.EmployerName)             .HasMaxLength(50)             .IsUnicode()             .IsRequired();          builder.Property(t => t.InfrastructureArea)            .IsRequired();          builder.Property(t => t.FloorCount)            .IsRequired();          builder.Property(t => t.UnitCount)            .IsRequired();          builder.Property(t => t.StartContractDate)           .IsRequired();          builder.Property(t => t.EndContractDate)           .IsRequired();          builder.Property(t => t.IsDelete)          .IsRequired();          builder.Property(t => t.ContractAmount).HasPrecision(36, 2);
        //builder.HasChangeTrackingStrategy(ChangeTrackingStrategy.ChangingAndChangedNotificationsWithOriginalValues);

    } } 